import{_ as a,o as t,c as r,a4 as i}from"./chunks/framework.2-Vke5-n.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"はじめての性能テスト","tagline":"Performance Test","actions":[{"theme":"brand","link":"./performance_test.md","text":"性能テスト"},{"theme":"alt","link":"./appendix.md","text":"Appendix"}]}},"headers":[],"relativePath":"documents/forPerformanceTest/index.md","filePath":"documents/forPerformanceTest/index.md"}'),l={name:"documents/forPerformanceTest/index.md"};function o(n,e,s,c,d,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>性能はシステム全体の品質やユーザーの利用体験を左右するため極めて重要である。</p><p>リリース直後にアクセスが集中してサイトが動かなくなったり、大量のデータ処理が終わらずに翌朝の業務に支障が出たりといったトラブルは後を絶たない。これらはすべて性能の問題であり、性能問題は性能テストによって事前に検出し、対処しなければならない。通常の機能テストとは別に「性能テスト」という専用の工程が必要とされるのは、机上での予測や開発環境での確認だけでは本番稼働時のリスクを排除できないためである。</p><p>しかしながら、性能テストは機能テストに比べて「何をどこまでやればいいのか」という基準が曖昧になりがちであり、場当たり的な実施に留まってしまうケースも少なくない。本ガイドラインは、性能テストの計画から実行、分析に至るまでの実践的なプロセスについてまとめたものである。</p><p>本ガイドラインの目的は次の通りである。</p><ul><li>性能テストの経験がない人でも、ステップバイステップで手順を理解し、現場で実践できるようになる</li><li>これまでなんとなく性能テストを実施していた人が、用語や考え方を体系的に理解し、理論にもとづいたテストを実践できるようになる</li></ul><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署／プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="前提" tabindex="-1">前提 <a class="header-anchor" href="#前提" aria-label="Permalink to &quot;前提&quot;">​</a></h2><p>本ガイドラインが想定しているシステムや環境は次の通りである。</p><h3 id="対象システム" tabindex="-1">対象システム <a class="header-anchor" href="#対象システム" aria-label="Permalink to &quot;対象システム&quot;">​</a></h3><p>本ガイドラインはWebアプリケーションの性能テストを前提として記述している。<br> 具体的には、エンドユーザー（ブラウザ）からのHTTPリクエストを起点とするオンライン処理や、それらに付随して発生する非同期処理、裏側のバッチ処理等を想定している。全体として主にサーバーサイドの性能検証に焦点を当てているが、Webフロントエンドの性能（例. JavaScriptの実行速度、レンダリング速度）なども一部切り出して説明する。</p><h3 id="インフラ環境" tabindex="-1">インフラ環境 <a class="header-anchor" href="#インフラ環境" aria-label="Permalink to &quot;インフラ環境&quot;">​</a></h3><p>オンプレミス環境ではなくAWS等のパブリッククラウド環境を想定している。<br> ただし、本ガイドラインに記載されている考え方の大部分はオンプレミス環境でも適用できるものである。オンプレミス固有の考慮事項などは、適宜補足を入れた上で説明する。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>Myers・Sandler・Badgett（2011）『The Art of Software Testing, Third Edition』Wiley</li><li>Molyneaux（2009）『The Art of Application Performance Testing』O&#39;Reilly Media</li><li>仲川・森下（2017）『Amazon Web Services負荷試験入門 ―クラウドの性能の引き出し方がわかる』技術評論社</li></ul><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 武田大輝、宮崎将太</li><li><strong>レビュアー</strong>: 真野隼記、澁川喜規、亀井隆徳、山田勇一、前原応光、村瀬善則</li></ul><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2026.06.10 <a href="https://future-architect.github.io/articles/20260610a/" target="_blank" rel="noreferrer">はじめての性能テストを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./performance_test.html">はじめての性能テスト</a></p></div>',21)])])}const m=a(l,[["render",o]]);export{u as __pageData,m as default};
